<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>The World's Most Valuable Companies in 2025 - Infographic</title>
  <script src="/app/vendor/infographic.min.js"></script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      width: 900px;
      background: #0a0f1e;
      font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
      color: #e2e8f0;
    }
    .poster {
      width: 900px;
      min-height: 1400px;
      background: linear-gradient(160deg, #0a0f1e 0%, #0d1631 60%, #0a1628 100%);
      padding: 48px 48px 56px 48px;
      display: flex;
      flex-direction: column;
      gap: 36px;
    }

    /* ── HEADER ── */
    .header {
      border-bottom: 1px solid rgba(99,179,237,0.25);
      padding-bottom: 28px;
    }
    .header-eyebrow {
      font-size: 10px;
      letter-spacing: 3px;
      text-transform: uppercase;
      color: #63b3ed;
      margin-bottom: 10px;
      font-weight: 600;
    }
    .header-title {
      font-size: 32px;
      font-weight: 800;
      color: #f7fafc;
      line-height: 1.15;
      letter-spacing: -0.5px;
      margin-bottom: 10px;
    }
    .header-title span { color: #63b3ed; }
    .header-sub {
      font-size: 13px;
      color: #94a3b8;
      line-height: 1.6;
      max-width: 680px;
    }

    /* ── HERO KPI ROW ── */
    .kpi-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }
    .kpi-card {
      background: rgba(255,255,255,0.04);
      border: 1px solid rgba(99,179,237,0.15);
      border-radius: 10px;
      padding: 20px 22px;
      position: relative;
      overflow: hidden;
    }
    .kpi-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 2px;
      background: linear-gradient(90deg, #63b3ed, #805ad5);
    }
    .kpi-card.gold::before { background: linear-gradient(90deg, #ecc94b, #ed8936); }
    .kpi-card.green::before { background: linear-gradient(90deg, #48bb78, #38b2ac); }
    .kpi-value {
      font-size: 28px;
      font-weight: 800;
      color: #f7fafc;
      letter-spacing: -1px;
      line-height: 1;
      margin-bottom: 6px;
    }
    .kpi-card.gold .kpi-value { color: #ecc94b; }
    .kpi-card.green .kpi-value { color: #68d391; }
    .kpi-label {
      font-size: 11px;
      color: #718096;
      text-transform: uppercase;
      letter-spacing: 1px;
      font-weight: 600;
    }

    /* ── SECTION HEADER ── */
    .section-label {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 16px;
    }
    .section-label-bar {
      width: 3px;
      height: 18px;
      background: linear-gradient(180deg, #63b3ed, #805ad5);
      border-radius: 2px;
      flex-shrink: 0;
    }
    .section-label-text {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 2.5px;
      text-transform: uppercase;
      color: #63b3ed;
    }

    /* ── TRILLION DOLLAR CHART ── */
    .chart-section { }
    .chart-title {
      font-size: 17px;
      font-weight: 700;
      color: #e2e8f0;
      margin-bottom: 4px;
    }
    .chart-subtitle {
      font-size: 12px;
      color: #718096;
      margin-bottom: 20px;
    }
    .bar-chart { display: flex; flex-direction: column; gap: 8px; }
    .bar-row {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .bar-rank {
      width: 22px;
      font-size: 10px;
      color: #4a5568;
      font-weight: 700;
      text-align: right;
      flex-shrink: 0;
    }
    .bar-name {
      width: 148px;
      font-size: 12px;
      color: #cbd5e0;
      font-weight: 600;
      flex-shrink: 0;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .bar-track {
      flex: 1;
      height: 22px;
      background: rgba(255,255,255,0.04);
      border-radius: 3px;
      overflow: hidden;
      position: relative;
    }
    .bar-fill {
      height: 100%;
      border-radius: 3px;
      transition: width 0.3s ease;
      position: relative;
    }
    .bar-fill.tier1 { background: linear-gradient(90deg, #4299e1, #63b3ed); }
    .bar-fill.tier2 { background: linear-gradient(90deg, #805ad5, #9f7aea); }
    .bar-fill.tier3 { background: linear-gradient(90deg, #2d3748, #4a5568); }
    .bar-fill.tier-intl { background: linear-gradient(90deg, #744210, #ed8936); opacity: 0.85; }
    .bar-cap {
      width: 68px;
      font-size: 11.5px;
      font-weight: 700;
      color: #e2e8f0;
      text-align: right;
      flex-shrink: 0;
    }
    .bar-flag {
      width: 18px;
      font-size: 12px;
      text-align: center;
      flex-shrink: 0;
    }
    /* trillion line annotation */
    .bar-divider {
      display: flex;
      align-items: center;
      gap: 8px;
      margin: 6px 0 4px 34px;
    }
    .bar-divider-line {
      flex: 1;
      height: 1px;
      background: rgba(237,212,75,0.3);
      margin-left: 148px;
    }
    .bar-divider-label {
      font-size: 9px;
      color: #ecc94b;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      font-weight: 700;
      white-space: nowrap;
    }

    /* ── TWO-COL BOTTOM ── */
    .two-col {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    /* ── COUNTRY GRID ── */
    .country-section {}
    .country-grid {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .country-row {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .country-flag { font-size: 18px; width: 26px; text-align: center; flex-shrink: 0; }
    .country-name {
      font-size: 12px;
      color: #a0aec0;
      font-weight: 600;
      width: 90px;
      flex-shrink: 0;
    }
    .country-dots {
      display: flex;
      gap: 4px;
      flex-wrap: wrap;
    }
    .dot {
      width: 14px;
      height: 14px;
      border-radius: 3px;
      background: #4299e1;
    }
    .dot.intl { background: #ed8936; }
    .country-count {
      font-size: 11px;
      font-weight: 800;
      color: #63b3ed;
      margin-left: 4px;
    }
    .country-count.intl { color: #ed8936; }
    .country-note {
      font-size: 10.5px;
      color: #4a5568;
      font-style: italic;
      margin-top: 4px;
    }

    /* ── SECTOR SECTION ── */
    .sector-section {}
    .sector-list { display: flex; flex-direction: column; gap: 10px; }
    .sector-item {
      display: flex;
      align-items: flex-start;
      gap: 10px;
    }
    .sector-icon {
      width: 28px;
      height: 28px;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      flex-shrink: 0;
      margin-top: 1px;
    }
    .sector-icon.tech { background: rgba(66,153,225,0.2); }
    .sector-icon.semi { background: rgba(128,90,213,0.2); }
    .sector-icon.energy { background: rgba(237,137,54,0.2); }
    .sector-icon.other { background: rgba(113,128,150,0.2); }
    .sector-body {}
    .sector-name {
      font-size: 12px;
      font-weight: 700;
      color: #e2e8f0;
      margin-bottom: 2px;
    }
    .sector-desc {
      font-size: 10.5px;
      color: #718096;
      line-height: 1.45;
    }

    /* ── PERSPECTIVE SECTION ── */
    .perspective-section {
      background: rgba(99,179,237,0.06);
      border: 1px solid rgba(99,179,237,0.18);
      border-radius: 12px;
      padding: 24px 28px;
    }
    .perspective-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin-top: 16px;
    }
    .persp-item { }
    .persp-num {
      font-size: 22px;
      font-weight: 800;
      color: #63b3ed;
      letter-spacing: -0.5px;
      line-height: 1;
      margin-bottom: 5px;
    }
    .persp-num.gold { color: #ecc94b; }
    .persp-num.green { color: #68d391; }
    .persp-label {
      font-size: 10.5px;
      color: #718096;
      line-height: 1.5;
    }
    .persp-divider {
      width: 1px;
      background: rgba(255,255,255,0.06);
    }

    /* ── FOOTER ── */
    .footer {
      border-top: 1px solid rgba(255,255,255,0.06);
      padding-top: 16px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .footer-source {
      font-size: 10px;
      color: #2d3748;
      letter-spacing: 0.5px;
    }
    .footer-date {
      font-size: 10px;
      color: #2d3748;
      font-weight: 600;
      letter-spacing: 1px;
    }
  </style>
</head>
