<div class="poster" id="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-eyebrow">Global Equity Markets · Mid-2025</div>
    <div class="header-title">The World's Most <span>Valuable</span> Companies</div>
    <div class="header-sub">
      A comparative snapshot of the top publicly traded companies by market capitalization —
      revealing extreme concentration at the top of the global equity hierarchy.
    </div>
  </div>

  <!-- KPI ROW -->
  <div class="kpi-row">
    <div class="kpi-card gold">
      <div class="kpi-value">$4.82T</div>
      <div class="kpi-label">NVIDIA — World's Most Valuable (#1)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">~$25.4T</div>
      <div class="kpi-label">Top 10 Combined Market Cap</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-value">$142.9T</div>
      <div class="kpi-label">Total Global Market Cap (10,796 Cos.)</div>
    </div>
  </div>

  <!-- TRILLION DOLLAR CLUB -->
  <div class="chart-section">
    <div class="section-label">
      <div class="section-label-bar"></div>
      <div class="section-label-text">The Trillion-Dollar Club</div>
    </div>
    <div class="chart-title">Top 11 Companies by Market Capitalization</div>
    <div class="chart-subtitle">All have crossed the $1 trillion threshold — the gap between the top 5 and the rest is immense</div>

    <div class="bar-chart">
      <!-- Rank 1 -->
      <div class="bar-row">
        <div class="bar-rank">1</div>
        <div class="bar-name">NVIDIA</div>
        <div class="bar-track"><div class="bar-fill tier1" style="width:100%"></div></div>
        <div class="bar-cap">$4.82 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>
      <!-- Rank 2 -->
      <div class="bar-row">
        <div class="bar-rank">2</div>
        <div class="bar-name">Alphabet (Google)</div>
        <div class="bar-track"><div class="bar-fill tier1" style="width:83.5%"></div></div>
        <div class="bar-cap">$4.03 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>
      <!-- Rank 3 -->
      <div class="bar-row">
        <div class="bar-rank">3</div>
        <div class="bar-name">Apple</div>
        <div class="bar-track"><div class="bar-fill tier1" style="width:80.3%"></div></div>
        <div class="bar-cap">$3.87 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>
      <!-- Rank 4 -->
      <div class="bar-row">
        <div class="bar-rank">4</div>
        <div class="bar-name">Microsoft</div>
        <div class="bar-track"><div class="bar-fill tier1" style="width:64.8%"></div></div>
        <div class="bar-cap">$3.12 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>
      <!-- Rank 5 -->
      <div class="bar-row">
        <div class="bar-rank">5</div>
        <div class="bar-name">Amazon</div>
        <div class="bar-track"><div class="bar-fill tier1" style="width:55.7%"></div></div>
        <div class="bar-cap">$2.69 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>

      <!-- Divider after top 5 -->
      <div style="display:flex;align-items:center;margin:4px 0 2px 182px;gap:8px;">
        <div style="flex:1;height:1px;background:rgba(237,212,75,0.25);"></div>
        <div style="font-size:9px;color:#ecc94b;letter-spacing:1.5px;text-transform:uppercase;font-weight:700;white-space:nowrap;">▲ Top 5 = $18.5T · ~13% of all global public equity</div>
        <div style="flex:0.05;height:1px;background:rgba(237,212,75,0.25);"></div>
      </div>

      <!-- Rank 6 -->
      <div class="bar-row">
        <div class="bar-rank">6</div>
        <div class="bar-name">Broadcom</div>
        <div class="bar-track"><div class="bar-fill tier2" style="width:39.2%"></div></div>
        <div class="bar-cap">$1.89 T</div>
        <div class="bar-flag">🇺🇸</div>
      </div>
      <!-- Rank 7 -->
      <div class="bar-row">
        <div class="bar-rank">7</div>
        <div class="bar-name">TSMC</div>
        <div class="bar-track"><div class="bar-fill tier-intl" style="width:39.1%"></div></div>
