import { createRequire } from 'module';
import { writeFileSync } from 'fs';
import { createCanvas, loadImage } from 'canvas';

const require = createRequire(import.meta.url);
const { renderToString } = require('/usr/local/lib/node_modules/@antv/infographic/lib/ssr');

const syntax = `infographic chart-bar-plain-text
data
  title The World's Most Valuable Companies 2025
  desc Top 11 by Market Cap (Trillion USD) · 15 of 20 are U.S. companies
  values
    - label NVIDIA #1 🇺🇸
      value 4.82
    - label Alphabet #2 🇺🇸
      value 4.03
    - label Apple #3 🇺🇸
      value 3.87
    - label Microsoft #4 🇺🇸
      value 3.12
    - label Amazon #5 🇺🇸
      value 2.69
    - label Broadcom #6 🇺🇸
      value 1.89
    - label TSMC #7 🇹🇼
      value 1.88
    - label Saudi Aramco #8 🇸🇦
      value 1.77
    - label Meta #9 🇺🇸
      value 1.71
    - label Tesla #10 🇺🇸
      value 1.46
    - label Berkshire #11 🇺🇸
      value 1.02
theme
  palette #4299e1 #63b3ed #805ad5 #4299e1 #63b3ed #9f7aea #ed8936 #dd6b20 #805ad5 #6b46c1 #718096
`;

try {
  const svg = await renderToString(syntax, { width: 900, height: 1200 });
  writeFileSync('/app/output/test_antv.svg', svg);
  console.log('SVG written, length:', svg.length);
} catch(e) {
  console.error('Error:', e.message);
  process.exit(1);
}

